{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Final Calculation",
          "intent": "Establish the protagonist's death and transition into the system.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Protagonist stands before the Tutorial Gate."
        },
        {
          "section_id": 2,
          "title": "Debugging the Tutorial",
          "intent": "Explore the mechanics of the 100% crit bug.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "The tutorial boss spawns in the arena."
        },
        {
          "section_id": 3,
          "title": "One-Shot Wonder",
          "intent": "Conclude the tutorial by obliterating the boss.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The protagonist enters the portal to the hub city."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Iron Gate Bureaucracy",
          "intent": "Introduce the hub city and the protagonist's initial struggle with registration.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The protagonist successfully registers at the Adventurer Guild."
        },
        {
          "section_id": 2,
          "title": "The Agility Loophole",
          "intent": "Experiment with the Speed-to-Crit conversion in a controlled environment.",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "The protagonist achieves a stable 100% crit-rate via Agility stacking."
        },
        {
          "section_id": 3,
          "title": "Dressed for Success",
          "intent": "Acquire the necessary gear to leverage the exploit in a real dungeon.",
          "section_role": "climax",
          "target_scene_count": 2,
          "end_condition": "The protagonist steps into the entrance of the Sunken Crypt."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "The No-Hit Run",
          "intent": "Begin the Sunken Crypt clear using the zero-hit strategy.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The protagonist reaches the mid-dungeon checkpoint without taking damage."
        },
        {
          "section_id": 2,
          "title": "Breaking the Leaderboard",
          "intent": "Escalate the dungeon difficulty while maintaining the hitless streak.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "The final boss door of the Sunken Crypt opens."
        },
        {
          "section_id": 3,
          "title": "Crypt-ic Victory",
          "intent": "Defeat the dungeon boss and trigger the server-wide leaderboard alert.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The protagonist exits the dungeon as the #1 ranked player."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Patch is Coming",
          "intent": "Gather intelligence on the upcoming nerf and locate the Admin Vault.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "The protagonist identifies the exact location of the Luck-Stabilizer."
        },
        {
          "section_id": 2,
          "title": "Heist of the Century",
          "intent": "Navigate the vault's security systems using movement exploits.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "The protagonist enters the vault's inner containment field."
        },
        {
          "section_id": 3,
          "title": "The Great Escape",
          "intent": "Secure the Luck-Stabilizer and flee the city before the gates lock.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The protagonist escapes the city walls as the bounty goes live."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Dead-Zone",
          "intent": "Enter the lawless Dead-Zone and encounter the System Corrector.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The protagonist loses the Corrector's tail for the first time."
        },
        {
          "section_id": 2,
          "title": "Pathfinding Pranks",
          "intent": "Use environmental hazards and mob aggro to evade the Corrector.",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "The protagonist reaches the entrance of the Source Code Temple."
        },
        {
          "section_id": 3,
          "title": "The Source Code Sanctuary",
          "intent": "Locate the hidden temple where the world's logic is exposed.",
          "section_role": "climax",
          "target_scene_count": 2,
          "end_condition": "The protagonist interfaces with the world's core logic terminal."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "Setting the Trap",
          "intent": "Prepare the unstable zone for a massive mathematical overflow.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "The Corrector enters the lag-trap zone."
        },
        {
          "section_id": 2,
          "title": "Division by Zero",
          "intent": "Engage the Corrector in a battle that pushes the physics engine to its limit.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "The environment begins to visually glitch as the overflow starts."
        },
        {
          "section_id": 3,
          "title": "Entity Deleted",
          "intent": "Trigger the overflow error to remove the Corrector from existence.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The Corrector is purged from the system registry."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Glitch Frontier",
          "intent": "Claim the unstable zone as a permanent base of operations.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The Glitch Zone's perimeter is secured against system scans."
        },
        {
          "section_id": 2,
          "title": "The New Meta",
          "intent": "Form a guild of outliers and establish the rules of the new reality.",
          "section_role": "aftermath",
          "target_scene_count": 3,
          "end_condition": "The protagonist sits on the 'Throne of Exploits' as the new update begins."
        }
      ]
    }
  ]
}

